using System; using System.Data.Entity; using System.Linq; using System.Web.Mvc; using MyStoreCustomer.Models; using MyStoreCustomer.Services;
namespace MyStoreCustomer.Controllers {
 [Authorize] public class CustomerController:Controller { private StoreDbContext db=new StoreDbContext();
 [HttpGet] public ActionResult MyOrder(string status="all",string search="",int page=1){ var customer=db.Customers.FirstOrDefault(x=>x.Username==User.Identity.Name); if(customer==null)return HttpNotFound(); var q=db.Orders.Include(x=>x.OrderDetails.Select(d=>d.Product)).Where(x=>x.CustomerID==customer.CustomerID); if(!String.IsNullOrWhiteSpace(search)){int id; string term=search.Trim(); q=q.Where(x=> (Int32.TryParse(term,out id)&&x.OrderID==id)||x.OrderDetails.Any(d=>d.Product.ProductName.Contains(term)));} if(status!="all")q=q.Where(x=>x.Status==status); int count=q.Count(); page=Math.Max(1,page); var model=new MyOrderViewModel{Search=search,Status=status,Page=page,PageSize=2,TotalCount=count,Orders=q.OrderByDescending(x=>x.OrderDate).ThenByDescending(x=>x.OrderID).Take(Math.Min(page*2,50)).ToList()}; return View(model); }
 [HttpGet] public ActionResult OrderDetails(int id){ var order=db.Orders.Include(x=>x.OrderDetails.Select(d=>d.Product)).FirstOrDefault(x=>x.OrderID==id&&x.Customer.Username==User.Identity.Name); if(order==null)return HttpNotFound(); return View(order); }
 [HttpPost,ValidateAntiForgeryToken] public ActionResult BuyAgain(int productId){ var p=db.Products.Find(productId); if(p==null)return HttpNotFound(); CartService.AddOne(Session,p); TempData["Message"]="Đã thêm sản phẩm vào giỏ hàng."; return RedirectToAction("MyOrder"); }
 protected override void Dispose(bool disposing){if(disposing)db.Dispose();base.Dispose(disposing);} }
}